
/* =====================================================================
   कंप्यूटर लैब  ·  data-mb-theory.js
   मदरबोर्ड मास्टरक्लास — भाग 1
     मास्टरक्लास 1 : मदरबोर्ड की नींव (PCB, इतिहास, फ़ॉर्म फैक्टर)
     मास्टरक्लास 2 : चिपसेट, नॉर्थ ब्रिज व साउथ ब्रिज
     मास्टरक्लास 3 : मदरबोर्ड के सारे कंपोनेंट
   ===================================================================== */

/* ---------- SVG बनाने के छोटे हेल्पर ---------- */
var MBF = 'Noto Sans Devanagari, sans-serif';
var MBM = 'IBM Plex Mono, monospace';
function MBfig(svg, cap) {
  /* सेक्शन रेंडरर ख़ुद <figure class="diagram"> लगाता है — यहाँ सिर्फ़ SVG + caption दीजिए */
  return svg + (cap ? '<figcaption>' + cap + '</figcaption>' : '');
}
function MBdefs(id, color) {
  return '<defs><marker id="' + id + '" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto">' +
    '<path d="M0,0 L10,4 L0,8 z" fill="' + (color || '#38bdf8') + '"/></marker></defs>';
}
function MBbox(x, y, w, h, t1, t2, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="12" fill="' + fill + '" stroke="' + stroke + '" stroke-width="2"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + (t2 ? -3 : 6)) + '" text-anchor="middle" fill="#e8eefc" font-size="' + (fs || 15) + '" font-weight="700" font-family="' + MBF + '">' + t1 + '</text>' +
    (t2 ? '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 17) + '" text-anchor="middle" fill="#9fb6d6" font-size="11.5" font-family="' + MBF + '">' + t2 + '</text>' : '') +
    '</g>';
}
function MBsmall(x, y, w, h, t, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="8" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.6"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 4) + '" text-anchor="middle" fill="#cfe3ff" font-size="' + (fs || 11.5) + '" font-weight="600" font-family="' + MBF + '">' + t + '</text></g>';
}
function MBline(x1, y1, x2, y2, label, color, arrow, mid, dash) {
  return '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="' + (color || '#38bdf8') + '" stroke-width="2.2"' +
    (arrow ? ' marker-end="url(#' + arrow + ')"' : '') + (dash ? ' stroke-dasharray="6 5"' : '') + '/>' +
    (label ? '<text x="' + ((mid != null) ? mid : (x1 + x2) / 2) + '" y="' + ((y1 + y2) / 2 - 7) + '" text-anchor="middle" fill="' + (color || '#7dd3fc') + '" font-size="11.5" font-family="' + MBF + '">' + label + '</text>' : '');
}
function MBtxt(x, y, t, color, fs, anchor, weight) {
  return '<text x="' + x + '" y="' + y + '" text-anchor="' + (anchor || 'middle') + '" fill="' + (color || '#9fb6d6') + '" font-size="' + (fs || 12.5) + '" font-weight="' + (weight || 600) + '" font-family="' + MBF + '">' + t + '</text>';
}

/* ---------- डायग्राम 1 : क्लासिक नॉर्थ/साउथ ब्रिज (नाम: MBchipsetClassic) ---------- */
/* window.MBdiagChipsetClassic -> app.js का alias "MBchipsetClassic" */
window.MBdiagChipsetClassic = function MBdiagChipsetClassic() {
  var s = '<svg viewBox="0 0 900 600" xmlns="http://www.w3.org/2000/svg">' + MBdefs('mbc1');
  s += MBtxt(450, 24, 'पुरानी (क्लासिक) मदरबोर्ड संरचना — दो चिप, दो स्तर', '#94a3c4', 13.5);
  s += MBbox(320, 40, 220, 74, 'CPU (प्रोसेसर)', 'Core + Cache', '#172a1f', '#22c55e');
  s += MBline(430, 118, 430, 152, 'FSB (Front Side Bus)', '#22c55e', 'mbc1');
  s += MBbox(280, 156, 300, 110, 'नॉर्थ ब्रिज (North Bridge)', 'Memory Controller Hub · तेज़ हिस्सा', '#1e2a4a', '#3b82f6');
  s += MBsmall(295, 214, 128, 40, 'RAM कंट्रोलर', '#0f1c33', '#60a5fa', 11);
  s += MBsmall(433, 214, 132, 40, 'ग्राफ़िक्स कंट्रोलर', '#0f1c33', '#60a5fa', 11);
  s += MBbox(40, 156, 200, 110, 'RAM (DIMM)', 'DDR / DDR2 / DDR3', '#2b2416', '#f59e0b');
  s += MBline(276, 211, 244, 211, 'मेमोरी बस', '#f59e0b', 'mbc1');
  s += MBbox(660, 156, 200, 110, 'AGP / PCIe x16', 'ग्राफ़िक्स कार्ड', '#2a1c31', '#a78bfa');
  s += MBline(584, 211, 656, 211, 'ग्राफ़िक्स बस', '#a78bfa', 'mbc1');
  s += MBline(430, 270, 430, 312, 'Hub Link / DMI / HyperTransport', '#22d3ee', 'mbc1');
  s += MBbox(260, 316, 340, 96, 'साउथ ब्रिज (South Bridge)', 'I/O Controller Hub · धीमा हिस्सा', '#1b2a44', '#22d3ee');
  /* नीचे की बस */
  s += MBline(430, 416, 430, 436, '', '#22d3ee');
  s += '<line x1="100" y1="436" x2="800" y2="436" stroke="#22d3ee" stroke-width="2.4"/>';
  var dev = [
    ['PCI स्लॉट', 'साउंड/नेटवर्क कार्ड'],
    ['IDE / SATA', 'HDD · ODD'],
    ['USB', 'पोर्ट व हेडर'],
    ['ऑडियो + LAN', 'AC-97 / HD Audio'],
    ['BIOS (SPI) + Super I/O', 'फ़र्मवेयर व पुराने पोर्ट'],
    ['RTC + CMOS + ISA', 'घड़ी, सेटिंग, पुराना स्लॉट']
  ];
  dev.forEach(function (d, i) {
    var x = 35 + i * 140;
    s += '<line x1="' + (x + 65) + '" y1="436" x2="' + (x + 65) + '" y2="462" stroke="#22d3ee" stroke-width="2"/>';
    s += MBsmall(x, 462, 130, 62, d[0], '#10202f', '#38bdf8', 11.5);
    s += MBtxt(x + 65, 512, d[1], '#8fb4dd', 10.5);
  });
  s += MBtxt(60, 578, '⚡ तेज़ रास्ता: CPU ↔ नॉर्थ ब्रिज ↔ RAM/GPU    |    🐢 धीमा रास्ता: साउथ ब्रिज ↔ USB/SATA/ऑडियो', '#94a3c4', 12, 'start');
  s += '</svg>';
  return MBfig(s, 'क्लासिक चिपसेट — नॉर्थ ब्रिज तेज़ काम (RAM + ग्राफ़िक्स) देखता था, साउथ ब्रिज धीमे I/O. दोनों के बीच एक बस (Hub Link / HT / DMI) रहती थी।');
};

